{
  "content": "import glob
import re

pat = re.compile(r'''(?:src|href|data-src|poster)\s*=\s*["']([^"']+)["']''', re.I)
exts = ('.mp4', '.webm', '.mov', '.avi', '.jpg', '.jpeg', '.png', '.gif', '.pdf', '.webp')

for f in sorted(glob.glob('fig_*.html')):
    s = open(f, encoding='utf-8', errors='ignore').read()
    urls = []
    for m in pat.finditer(s):
        u = m.group(1)
        if u.lower().endswith(exts) or 'upload' in u.lower() or 'media' in u.lower():
            if u not in urls:
                urls.append(u)
    print('=====', f)
    for u in urls:
        print('   ', u)
    # also look for object/embed
    for m in re.finditer(r'(?is)<(object|embed|video|source)[^>]*>', s):
        print('  TAG', m.group(0)[:220])
",
  "file_path": "/workspace\find_media.py"
}

